function validate([caption]) {
  if (typeof caption !== 'string' || caption.length < 1 || caption.length > 150) return 'caption needs 1 to 150 characters.';
  if (!/^[A-Za-z ]+$/.test(caption)) return 'caption may contain only English letters and spaces.';
  return null;
}

reference:
function generateTag(caption) {
  const words = caption.split(' ').filter(word => word.length > 0);
  let tag = '#';
  for (let i = 0; i < words.length; i++) {
    const word = words[i].toLowerCase();
    if (i === 0) {
      tag += word;
    } else {
      tag += word[0].toUpperCase() + word.slice(1);
    }
  }
  return tag.slice(0, 100);
}

brute:
function generateTag(caption) {
  // Walk the caption one character at a time; a letter right after a space (or at index 0) starts a word.
  let tag = '#';
  let wordsSeen = 0;
  for (let i = 0; i < caption.length; i++) {
    const ch = caption[i];
    if (ch === ' ') continue;
    const startsWord = i === 0 || caption[i - 1] === ' ';
    if (startsWord) wordsSeen++;
    tag += startsWord && wordsSeen > 1 ? ch.toUpperCase() : ch.toLowerCase();
  }
  return tag.length > 100 ? tag.substring(0, 100) : tag;
}

