function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  // Long captions (some of them small inputs too, since the brute force is linear) exercise the 100-character cut.
  const long = size === 'large' || rand() < 0.3;
  const length = long ? 95 + Math.floor(rand() * 56) : 1 + Math.floor(rand() * 16);
  const spaceRate = [0.05, 0.2, 0.45][Math.floor(rand() * 3)];
  let caption = '';
  for (let i = 0; i < length; i++) caption += rand() < spaceRate ? ' ' : letters[Math.floor(rand() * letters.length)];
  return [caption];
}
